plugins {
    id("com.android.application")
}

// The Lembas watch face: Watch Face Format XML, images and fonts only. The watch's own renderer
// draws and animates it; there is no code in this APK. res/raw/watchface.xml, the images and the
// fonts are generated by wear/tools/make_watchface.py (run in CI).
android {
    namespace = "com.middleearth.launcher.watchface"
    compileSdk = 36

    defaultConfig {
        applicationId = "com.middleearth.launcher.watchface"
        minSdk = 34          // Watch Face Format 2 (weather): Wear OS 5 and later
        targetSdk = 36
        val build = (System.getenv("LEMBAS_BUILD") ?: "1").toInt()
        versionCode = build
        versionName = "1.$build"
    }

    val keystore = System.getenv("LEMBAS_KEYSTORE")?.let { file(it) }
    signingConfigs {
        if (keystore != null && keystore.exists()) create("lembas") {
            storeFile = keystore
            storePassword = System.getenv("LEMBAS_KEYSTORE_PASSWORD")
            keyAlias = System.getenv("LEMBAS_KEY_ALIAS") ?: "lembas"
            keyPassword = System.getenv("LEMBAS_KEY_PASSWORD")
        }
    }

    buildTypes {
        release {
            isMinifyEnabled = false
            signingConfig = signingConfigs.findByName("lembas") ?: signingConfigs.getByName("debug")
        }
    }
    lint {
        abortOnError = false
        checkReleaseBuilds = false
    }
}
